   417→          </div>
   418→        )}
   419→      </div>
   420→
   421→      {/* Capacity bar */}
   422→      <div className="space-y-1.5">
   423→        <div className="flex items-center justify-between text-xs">
   424→          <span className="text-muted-foreground">
   425→            <Users size={10} className="inline mr-1" />
   426→            {enrolled} Anmeldung{enrolled !== 1 ? 'en' : ''}
   427→          </span>
   428→          <span className={`font-600 ${isFull ? 'text-red-600' : 'text-muted-foreground'}`}>
   429→            {capacity > 0 ? `${capacity} Plätze` : 'Unbegrenzt'}
   430→          </span>
   431→        </div>
   432→        {capacity > 0 && (
   433→          <div className="h-1.5 bg-muted rounded-full overflow-hidden">
   434→            <div
   435→              className={`h-full rounded-full transition-all ${isFull ? 'bg-red-400' : isAlmostFull ? 'bg-amber-400' : 'bg-primary'}`}
   436→              style={{ width: `${fillPct}%` }}
   437→            />
   438→          </div>
   439→        )}
   440→      </div>
   441→
   442→      <div className="mt-3 pt-3 border-t border-border/60 flex items-center justify-between">
   443→        <span className="text-xs text-muted-foreground">Anmeldungen verwalten</span>
   444→        <ChevronRight size={14} className="text-muted-foreground group-hover:text-primary group-hover:translate-x-0.5 transition-all" />
   445→      </div>
   446→    </button>
   447→  );
   448→}
   449→
   450→// ---- KPI Bar ----
   451→function KpiBar({ kurse, anmeldungen }: { kurse: EnrichedKurs[]; anmeldungen: Anmeldungen[] }) {
   452→  const totalKurse = kurse.length;
   453→  const totalAnmeldungen = anmeldungen.length;
   454→  const bezahlt = anmeldungen.filter(a => a.fields.bezahlt).length;
   455→  const ausstehend = totalAnmeldungen - bezahlt;
   456→  const ausgebucht = kurse.filter(k => {
   457→    const c = k.fields.max_teilnehmer ?? 0;
   458→    return c > 0 && k.anmeldungenCount >= c;
   459→  }).length;
   460→
   461→  return (
   462→    <div className="grid grid-cols-2 lg:grid-cols-4 gap-3 mb-8">
   463→      {[
   464→        { label: 'Kurse gesamt', value: totalKurse, icon: BookOpen, color: 'text-primary', bg: 'bg-primary/8' },
   465→        { label: 'Anmeldungen', value: totalAnmeldungen, icon: Users, color: 'text-violet-600', bg: 'bg-violet-50' },
   466→        { label: 'Bezahlt', value: bezahlt, icon: CheckCircle2, color: 'text-emerald-600', bg: 'bg-emerald-50' },
   467→        { label: 'Ausstehend', value: ausstehend, icon: Clock, color: 'text-amber-600', bg: 'bg-amber-50' },
   468→      ].map(({ label, value, icon: Icon, color, bg }) => (
   469→        <div key={label} className="bg-card border border-border rounded-2xl px-4 py-3 flex items-center gap-3">
   470→          <div className={`w-9 h-9 rounded-xl ${bg} flex items-center justify-center shrink-0`}>
   471→            <Icon size={16} className={color} />
   472→          </div>
   473→          <div>
   474→            <p className="text-2xl font-800 text-foreground leading-none">{value}</p>
   475→            <p className="text-xs text-muted-foreground mt-0.5">{label}</p>
   476→          </div>
   477→        </div>
   478→      ))}
   479→    </div>
   480→  );
   481→}
   482→
   483→// ---- Main Dashboard ----
   484→export default function DashboardOverview() {
   485→  const [kurse, setKurse] = useState<Kurse[]>([]);
   486→  const [dozenten, setDozenten] = useState<Dozenten[]>([]);
   487→  const [raeume, setRaeume] = useState<Raeume[]>([]);
   488→  const [anmeldungen, setAnmeldungen] = useState<Anmeldungen[]>([]);
   489→  const [teilnehmer, setTeilnehmer] = useState<Teilnehmer[]>([]);
   490→  const [loading, setLoading] = useState(true);
   491→  const [error, setError] = useState<Error | null>(null);
   492→
   493→  const [selectedKurs, setSelectedKurs] = useState<EnrichedKurs | null>(null);
   494→  const [showAddKurs, setShowAddKurs] = useState(false);
   495→  const [filterSearch, setFilterSearch] = useState('');
   496→  const [filterStatus, setFilterStatus] = useState<'all' | 'available' | 'full'>('all');
   497→
   498→  const fetchAll = async () => {
   499→    try {
   500→      const [k, d, r, a, t] = await Promise.all([
   501→        LivingAppsService.getKurse(),
   502→        LivingAppsService.getDozenten(),
   503→        LivingAppsService.getRaeume(),
   504→        LivingAppsService.getAnmeldungen(),
   505→        LivingAppsService.getTeilnehmer(),
   506→      ]);
   507→      setKurse(k);
   508→      setDozenten(d);
   509→      setRaeume(r);
   510→      setAnmeldungen(a);
   511→      setTeilnehmer(t);
   512→    } catch (err) {
   513→      setError(err instanceof Error ? err : new Error('Fehler beim Laden'));
   514→    } finally {
   515→      setLoading(false);
   516→    }
   517→  };
   518→
   519→  useEffect(() => { fetchAll(); }, []);
   520→
   521→  const dozentenMap = useMemo(() => {
   522→    const m = new Map<string, Dozenten>();
   523→    dozenten.forEach(d => m.set(d.record_id, d));
   524→    return m;
   525→  }, [dozenten]);
   526→
   527→  const raeumeMap = useMemo(() => {
   528→    const m = new Map<string, Raeume>();
   529→    raeume.forEach(r => m.set(r.record_id, r));
   530→    return m;
   531→  }, [raeume]);
   532→
   533→  const teilnehmerMap = useMemo(() => {
   534→    const m = new Map<string, Teilnehmer>();
   535→    teilnehmer.forEach(t => m.set(t.record_id, t));
   536→    return m;
   537→  }, [teilnehmer]);
   538→
   539→  const enrichedKurse: EnrichedKurs[] = useMemo(() => {
   540→    return kurse.map(k => {
   541→      const dozentId = extractRecordId(k.fields.dozent);
   542→      const raumId = extractRecordId(k.fields.raum);
   543→      const kursAnmeldungen = anmeldungen.filter(a => extractRecordId(a.fields.kurs) === k.record_id);
   544→
   545→      const enrichedAnmeldungen: EnrichedAnmeldung[] = kursAnmeldungen.map(a => {
   546→        const tnId = extractRecordId(a.fields.teilnehmer);
   547→        const tn = tnId ? teilnehmerMap.get(tnId) : undefined;
   548→        return {
   549→          ...a,
   550→          teilnehmerName: tn ? `${tn.fields.vorname ?? ''} ${tn.fields.nachname ?? ''}`.trim() : 'Unbekannt',
   551→        };
   552→      });
   553→
   554→      return {
   555→        ...k,
   556→        dozentName: dozentId
   557→          ? `${dozentenMap.get(dozentId)?.fields.vorname ?? ''} ${dozentenMap.get(dozentId)?.fields.nachname ?? ''}`.trim()
   558→          : '',
   559→        raumName: raumId
   560→          ? `${raeumeMap.get(raumId)?.fields.raumname ?? ''}`
   561→          : '',
   562→        anmeldungenCount: kursAnmeldungen.length,
   563→        anmeldungen: enrichedAnmeldungen,
   564→      };
   565→    });
   566→  }, [kurse, anmeldungen, dozentenMap, raeumeMap, teilnehmerMap]);
   567→
   568→  const filteredKurse = useMemo(() => {
   569→    return enrichedKurse.filter(k => {
   570→      const matchSearch = filterSearch === '' ||
   571→        (k.fields.titel ?? '').toLowerCase().includes(filterSearch.toLowerCase()) ||
   572→        k.dozentName.toLowerCase().includes(filterSearch.toLowerCase());
   573→      const cap = k.fields.max_teilnehmer ?? 0;
   574→      const isFull = cap > 0 && k.anmeldungenCount >= cap;
   575→      const matchStatus =
   576→        filterStatus === 'all' ||
   577→        (filterStatus === 'available' && !isFull) ||
   578→        (filterStatus === 'full' && isFull);
   579→      return matchSearch && matchStatus;
   580→    });
   581→  }, [enrichedKurse, filterSearch, filterStatus]);
   582→
   583→  const handleAddKurs = async (fields: Kurse['fields']) => {
   584→    await LivingAppsService.createKurseEntry(fields);
   585→    await fetchAll();
   586→  };
   587→
   588→  const handleAddAnmeldung = async (kursId: string, teilnehmerId: string) => {
   589→    await LivingAppsService.createAnmeldungenEntry({
   590→      kurs: createRecordUrl(APP_IDS.KURSE, kursId),
   591→      teilnehmer: createRecordUrl(APP_IDS.TEILNEHMER, teilnehmerId),
   592→      anmeldedatum: new Date().toISOString().split('T')[0],
   593→      bezahlt: false,
   594→    });
   595→    const updated = await LivingAppsService.getAnmeldungen();
   596→    setAnmeldungen(updated);
   597→    // Update selectedKurs with new data
   598→    setSelectedKurs(prev => {
   599→      if (!prev) return prev;
   600→      const newKursAnmeldungen = updated.filter(a => extractRecordId(a.fields.kurs) === prev.record_id);
   601→      const enrichedAnmeldungen: EnrichedAnmeldung[] = newKursAnmeldungen.map(a => {
   602→        const tnId = extractRecordId(a.fields.teilnehmer);
   603→        const tn = tnId ? teilnehmerMap.get(tnId) : undefined;
   604→        return {
   605→          ...a,
   606→          teilnehmerName: tn ? `${tn.fields.vorname ?? ''} ${tn.fields.nachname ?? ''}`.trim() : 'Unbekannt',
   607→        };
   608→      });
   609→      return { ...prev, anmeldungenCount: newKursAnmeldungen.length, anmeldungen: enrichedAnmeldungen };
   610→    });
   611→  };
   612→
   613→  const handleDeleteAnmeldung = async (id: string) => {
   614→    await LivingAppsService.deleteAnmeldungenEntry(id);
   615→    const updated = await LivingAppsService.getAnmeldungen();
   616→    setAnmeldungen(updated);
   617→    setSelectedKurs(prev => {
   618→      if (!prev) return prev;
   619→      const newKursAnmeldungen = updated.filter(a => extractRecordId(a.fields.kurs) === prev.record_id);
   620→      const enrichedAnmeldungen: EnrichedAnmeldung[] = newKursAnmeldungen.map(a => {
   621→        const tnId = extractRecordId(a.fields.teilnehmer);
   622→        const tn = tnId ? teilnehmerMap.get(tnId) : undefined;
   623→        return {
   624→          ...a,
   625→          teilnehmerName: tn ? `${tn.fields.vorname ?? ''} ${tn.fields.nachname ?? ''}`.trim() : 'Unbekannt',
   626→        };
   627→      });
   628→      return { ...prev, anmeldungenCount: newKursAnmeldungen.length, anmeldungen: enrichedAnmeldungen };
   629→    });
   630→  };
   631→
   632→  if (loading) {
   633→    return (
   634→      <div className="space-y-6">
   635→        <div className="flex items-center justify-between">
   636→          <Skeleton className="h-8 w-48" />
   637→          <Skeleton className="h-9 w-36" />
   638→        </div>
   639→        <div className="grid grid-cols-2 lg:grid-cols-4 gap-3">
   640→          {[...Array(4)].map((_, i) => <Skeleton key={i} className="h-16 rounded-2xl" />)}
   641→        </div>
   642→        <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-3 gap-4">
   643→          {[...Array(6)].map((_, i) => <Skeleton key={i} className="h-52 rounded-2xl" />)}
   644→        </div>
   645→      </div>
   646→    );
   647→  }
   648→
   649→  if (error) {
   650→    return (
   651→      <div className="flex flex-col items-center justify-center py-24 gap-4">
   652→        <div className="w-12 h-12 rounded-2xl bg-destructive/10 flex items-center justify-center">
   653→          <AlertCircle size={22} className="text-destructive" />
   654→        </div>
   655→        <div className="text-center">
   656→          <h3 className="font-600 text-foreground mb-1">Fehler beim Laden</h3>
   657→          <p className="text-sm text-muted-foreground max-w-xs">{error.message}</p>
   658→        </div>
   659→        <Button variant="outline" size="sm" onClick={() => { setError(null); setLoading(true); fetchAll(); }}>
   660→          Erneut versuchen
   661→        </Button>
   662→      </div>
   663→    );
   664→  }
   665→
   666→  return (
   667→    <div className="space-y-0">
   668→      {/* Header */}
   669→      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-6">
   670→        <div>
   671→          <h1 className="text-2xl font-800 text-foreground tracking-tight">Kursübersicht</h1>
   672→          <p className="text-sm text-muted-foreground mt-0.5">
   673→            {enrichedKurse.length} Kurs{enrichedKurse.length !== 1 ? 'e' : ''} · Klicken zum Verwalten
   674→          </p>
   675→        </div>
   676→        <Button onClick={() => setShowAddKurs(true)} className="gap-2 shrink-0">
   677→          <Plus size={16} />
   678→          Neuer Kurs
   679→        </Button>
   680→      </div>
   681→
   682→      {/* KPI Bar */}
   683→      <KpiBar kurse={enrichedKurse} anmeldungen={anmeldungen} />
   684→
   685→      {/* Filter Bar */}
   686→      <div className="flex flex-col sm:flex-row gap-2 mb-5">
   687→        <div className="relative flex-1">
   688→          <Search size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground" />
   689→          <Input
   690→            value={filterSearch}
   691→            onChange={e => setFilterSearch(e.target.value)}
   692→            placeholder="Kurse oder Dozent suchen…"
   693→            className="pl-9 h-9 text-sm"
   694→          />
   695→          {filterSearch && (
   696→            <button
   697→              onClick={() => setFilterSearch('')}
   698→              className="absolute right-2.5 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground"
   699→            >
   700→              <X size={13} />
   701→            </button>
   702→          )}
   703→        </div>
   704→        <div className="flex gap-1.5">
   705→          {(['all', 'available', 'full'] as const).map(f => (
   706→            <button
   707→              key={f}
   708→              onClick={() => setFilterStatus(f)}
   709→              className={`px-3 py-1.5 rounded-lg text-xs font-600 border transition-colors ${
   710→                filterStatus === f
   711→                  ? 'bg-primary text-primary-foreground border-primary'
   712→                  : 'bg-card text-muted-foreground border-border hover:border-primary/40'
   713→              }`}
   714→            >
   715→              {f === 'all' ? 'Alle' : f === 'available' ? 'Verfügbar' : 'Ausgebucht'}
   716→            </button>
   717→          ))}
   718→        </div>
   719→      </div>
   720→
   721→      {/* Course Grid */}
   722→      {filteredKurse.length === 0 ? (
   723→        <div className="flex flex-col items-center justify-center py-24 gap-4">
   724→          <div className="w-14 h-14 rounded-2xl bg-muted flex items-center justify-center">
   725→            <BookOpen size={24} className="text-muted-foreground" />
   726→          </div>
   727→          <div className="text-center">
   728→            <h3 className="font-600 text-foreground mb-1">
   729→              {filterSearch || filterStatus !== 'all' ? 'Keine Kurse gefunden' : 'Noch keine Kurse'}
   730→            </h3>
   731→            <p className="text-sm text-muted-foreground">
   732→              {filterSearch || filterStatus !== 'all'
   733→                ? 'Versuche andere Filtereinstellungen'
   734→                : 'Erstelle deinen ersten Kurs'}
   735→            </p>
   736→          </div>
   737→          {!(filterSearch || filterStatus !== 'all') && (
   738→            <Button onClick={() => setShowAddKurs(true)} className="gap-2">
   739→              <Plus size={15} />
   740→              Ersten Kurs erstellen
   741→            </Button>
   742→          )}
   743→        </div>
   744→      ) : (
   745→        <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-3 gap-4">
   746→          {filteredKurse.map(k => (
   747→            <KursCard key={k.record_id} kurs={k} onClick={() => setSelectedKurs(k)} />
   748→          ))}
   749→        </div>
   750→      )}
   751→
   752→      {/* Dialogs */}
   753→      {selectedKurs && (
   754→        <EnrollmentDialog
   755→          kurs={selectedKurs}
   756→          anmeldungen={selectedKurs.anmeldungen}
   757→          teilnehmerList={teilnehmer}
   758→          onClose={() => setSelectedKurs(null)}
   759→          onAdd={handleAddAnmeldung}
   760→          onDelete={handleDeleteAnmeldung}
   761→        />
   762→      )}
   763→      {showAddKurs && (
   764→        <AddKursDialog
   765→          dozenten={dozenten}
   766→          raeume={raeume}
   767→          onClose={() => setShowAddKurs(false)}
